mod tests {
    use super::*;

    #[test]
    fn picks_the_furthest() {
        let readings = [(1.0, 1.0), (3.0, 4.0), (0.0, 2.0)];
        assert_eq!(furthest(&readings), Some((3.0, 4.0)));
    }

    #[test]
    fn empty_input_has_no_answer() {
        assert_eq!(furthest(&[]), None);
    }
}

