pub trait OutputPin {
    fn set_state(&mut self, high: bool);
    fn state(&self) -> bool;
}

pub struct Led {
    pin: impl OutputPin,
}

impl Led {
    pub fn new(pin: impl OutputPin) -> Self {
        Led { pin }
    }

    pub fn toggle(&mut self) {
        let now = self.pin.state();
        self.pin.set_state(!now);
    }

    pub fn is_on(&self) -> bool {
        self.pin.state()
    }
}

pub struct FakePin {
    pub high: bool,
}

impl OutputPin for FakePin {
    fn set_state(&mut self, high: bool) {
        self.high = high;
    }
    fn state(&self) -> bool {
        self.high
    }
}

