mod tests {
    use super::*;

    #[test]
    fn toggles_the_underlying_pin() {
        let mut led = Led::new(FakePin { high: false });
        assert!(!led.is_on());
        led.toggle();
        assert!(led.is_on());
        led.toggle();
        assert!(!led.is_on());
